def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    from collections import deque
    from fractions import Fraction

    jump = {a: b for a, b in jumps}
    resolved = list(range(n + 1))

    for cell in range(n + 1):
        path = []
        current = cell
        while current in jump:
            path.append(current)
            current = jump[current]
        for start in path:
            resolved[start] = current

    transitions = [[] for _ in range(n)]
    reverse = [[] for _ in range(n + 1)]

    for cell in range(n):
        for roll in range(1, m + 1):
            destination = cell + roll
            if destination > n:
                destination = 2 * n - destination
            destination = resolved[destination]
            transitions[cell].append(destination)
            reverse[destination].append(cell)

    reachable = [False] * (n + 1)
    reachable[0] = True
    queue = deque([0])

    while queue:
        cell = queue.popleft()
        if cell == n:
            continue
        for destination in transitions[cell]:
            if not reachable[destination]:
                reachable[destination] = True
                queue.append(destination)

    can_finish = [False] * (n + 1)
    can_finish[n] = True
    queue = deque([n])

    while queue:
        cell = queue.popleft()
        for previous in reverse[cell]:
            if not can_finish[previous]:
                can_finish[previous] = True
                queue.append(previous)

    if any(reachable[cell] and not can_finish[cell] for cell in range(n)):
        return None

    states = [cell for cell in range(n) if reachable[cell]]
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)

    matrix = [[0] * (size + 1) for _ in range(size)]
    for i, cell in enumerate(states):
        matrix[i][i] = m
        matrix[i][size] = m
        for destination in transitions[cell]:
            if destination != n:
                matrix[i][index[destination]] -= 1

    previous_pivot = 1
    for column in range(size - 1):
        if matrix[column][column] == 0:
            for row in range(column + 1, size):
                if matrix[row][column] != 0:
                    matrix[column], matrix[row] = matrix[row], matrix[column]
                    break

        pivot = matrix[column][column]
        for row in range(column + 1, size):
            factor = matrix[row][column]
            for j in range(column + 1, size + 1):
                matrix[row][j] = (
                    matrix[row][j] * pivot - factor * matrix[column][j]
                ) // previous_pivot
            matrix[row][column] = 0
        previous_pivot = pivot

    solution = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            value -= matrix[i][j] * solution[j]
        solution[i] = value / matrix[i][i]

    answer = solution[index[0]]
    return [answer.numerator, answer.denominator]
